// Get roster data from MySQL query
const rosterData = $input.all();

const currentDateTime = new Date().toISOString();

// Filter out non-data rows (SET statement results have no id/date)
const engineers = rosterData
  .filter(item => item.json.id != null && item.json.date != null)
  .map(item => ({
    id: item.json.id,
    employee_name: item.json.employee_name || '',
    role: item.json.role || '',
    shift: item.json.shift || '',
    date: item.json.date.split('T')[0]
  }));

const response = {
  symbol: 'ROSTER',
  name: 'Daily-Roster',
  datetime: currentDateTime,
  engineers: engineers
};

return [{ json: response }];

