const validSymbols = ['5G', 'FIBER', 'IOT', 'SUB6', 'UBR', '4G', 'ROSTER'];
const apiKey = $json.query.apikey;
const symbol = $json.query.symbol;

if (apiKey !== 'e03fc53524454ab8b65d91b23c669cc5') {
  throw new Error('Unauthorized API Key');
}

if (!validSymbols.includes(symbol)) {
  return [{
    json: {
      detail: `Invalid symbol: ${symbol}. Choose from {'5G', 'FIBER', 'IOT', 'SUB6', 'UBR', '4G', 'ROSTER'}`
    }
  }];
}

return [{ json: { symbol } }];

