// Get UBR statistics from MySQL query
const data = $input.first().json;

// Calculate percent change
const today = parseInt(data.today) || 100;
const yesterday = parseInt(data.yesterday) || 200;
let percentChange = '';

if (yesterday > 0) {
  const change = ((today - yesterday) / yesterday) * 100;
  percentChange = change > 0 ? `+${change.toFixed(1)}%` : `${change.toFixed(1)}%`;
}

// Create the response in the requested format
const response = {
  symbol: 'UBR',
  name: 'AirFiber-UBR',
  datetime: new Date().toISOString(),
  today: today.toString(),
  yesterday: yesterday.toString(),
  overall: (parseInt(data.overall) || 300).toString(),
  percent_change: percentChange,
  last_week: {
    low: (parseInt(data.week_low) || 800).toString(),
    high: (parseInt(data.week_high) || 1000).toString()
  }
};

return [{ json: response }];

